root = os.path.abspath(sys.argv[1] if len(sys.argv) > 1 else ".")
if not os.path.isfile(os.path.join(root, "src", "web.cpp")):
    # maybe the user is one level above
    sub = os.path.join(root, "Brothers_Motorshop-main")
    if os.path.isfile(os.path.join(sub, "src", "web.cpp")): root = sub
    else: sys.exit("ERROR: hindi makita ang src/web.cpp sa " + root + "\nI-run ito sa loob ng Brothers_Motorshop-main folder, o ibigay ang path.")
zf = zipfile.ZipFile(io.BytesIO(base64.b64decode(DATA)))
for name in zf.namelist():
    dst = os.path.join(root, *name.split("/"))
    if os.path.isfile(dst) and not os.path.isfile(dst + ".bak"): shutil.copy2(dst, dst + ".bak")
    with open(dst, "wb") as f: f.write(zf.read(name))
    print("updated", name)
w = open(os.path.join(root, "src", "web.cpp"), encoding="utf-8").read()
assert "re_asset.h" in w and "/static/re.jpg" in w and "re-badge" in w, "web.cpp not patched!"
assert "re-badge" in open(os.path.join(root, "src", "web_assets.h"), encoding="utf-8").read()
print("\nOK - na-install na sa", root)
print("Susunod: make   (o)   g++ -std=c++17 -O2 -Ithird_party src/*.cpp -o re_parts_tracker -pthread")
